import React, { useEffect } from 'react'
import styled from 'styled-components'

const AdContainer = styled.div`
  margin: ${props => props.margin || '32px 0'};
  padding: ${props => props.padding || '16px 0'};
  min-height: ${props => {
    switch(props.format) {
      case 'horizontal': return '90px';
      case 'vertical': return '600px';
      case 'square': return '250px';
      case 'article': return '250px';
      default: return 'auto';
    }
  }};
  display: flex;
  justify-content: center;
  align-items: center;
  background: ${props => props.theme?.name === 'dark' ? '#1a1a1a' : '#f9fafb'};
  border-radius: 12px;
  overflow: hidden;
  
  @media (max-width: 768px) {
    margin: 20px 0;
    padding: 12px 0;
  }
  
  /* 개발 모드에서 광고 영역 표시 */
  ${props => props.isDev && `
    border: 2px dashed ${props.theme?.name === 'dark' ? '#4b5563' : '#d1d5db'};
    position: relative;
    
    &::before {
      content: 'AdSense ${props.format || 'auto'} Ad Space';
      position: absolute;
      top: 50%;
      left: 50%;
      transform: translate(-50%, -50%);
      color: ${props.theme?.name === 'dark' ? '#6b7280' : '#9ca3af'};
      font-size: 14px;
      font-weight: 500;
      text-transform: uppercase;
      letter-spacing: 0.05em;
    }
  `}
`

const AdSense = ({ 
  client,
  slot,
  format = 'auto',
  responsive = true,
  margin,
  padding,
  ...props 
}) => {
  const isDev = process.env.NODE_ENV === 'development'
  
  useEffect(() => {
    if (!isDev && typeof window !== 'undefined') {
      try {
        // AdSense 스크립트가 로드되었는지 확인
        if (window.adsbygoogle) {
          (window.adsbygoogle = window.adsbygoogle || []).push({})
        }
      } catch (error) {
        console.error('AdSense loading error:', error)
      }
    }
  }, [isDev])
  
  // 개발 모드에서는 플레이스홀더만 표시
  if (isDev || !client || !slot) {
    return (
      <AdContainer 
        isDev={true} 
        format={format}
        margin={margin}
        padding={padding}
      />
    )
  }
  
  return (
    <AdContainer 
      format={format}
      margin={margin}
      padding={padding}
    >
      <ins
        className="adsbygoogle"
        style={{ 
          display: 'block',
          width: '100%',
          height: 'auto',
        }}
        data-ad-client={client}
        data-ad-slot={slot}
        data-ad-format={format}
        data-full-width-responsive={responsive}
        {...props}
      />
    </AdContainer>
  )
}

export default AdSense